toolArgs.file_text:
.message-bubble {
    position: relative;
    padding: 6px 16px;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #f7f7fa;
}

.message-bubble.highlighted {
    background: #fffbe6;
    border-left: 3px solid #f0c040;
    padding-left: 13px;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #1a1a2e;
}

.timestamp {
    font-size: 0.75rem;
    color: #888;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.45;
    color: #2e2e3a;
    word-break: break-word;
    white-space: pre-wrap;
}

.thread-link {
    background: none;
    border: none;
    color: #5865f2;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 12px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #d0d0d0;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
}

.action-btn {
    background: none;
    border: none;
    font-size: 1rem;
    padding: 4px 6px;
    cursor: pointer;
    border-radius: 4px;
    line-height: 1;
}

.action-btn:hover {
    background: #f0f0f4;
}

