@namespace sv_419c21f37d354afa89ea84a5a48daf0b.Components.Pages.Chat
@using sv_419c21f37d354afa89ea84a5a48daf0b.Services

<aside class="channel-sidebar">
    <div class="sidebar-header">
        <h2>Channels</h2>
    </div>
    <nav class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelListItem Channel="channel"
                             IsActive="channel.Id == SelectedChannelId"
                             OnSelected="OnChannelSelected" />
        }
    </nav>
</aside>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

.channel-sidebar {
    width: 100%;
    height: 100%;
    background: #2b2d42;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}

.sidebar-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
    font-weight: 700;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 6px 0;
}

