@namespace sv_419c21f37d354afa89ea84a5a48daf0b.Components.Pages.Chat
@using sv_419c21f37d354afa89ea84a5a48daf0b.Services

<div class="message-list" @ref="scrollContainer">
    @if (HasMore)
    {
        <div class="load-more">
            <button class="load-more-btn" @onclick="OnLoadMore" disabled="@IsLoadingMore">
                @(IsLoadingMore ? "Loading…" : "↑ Load older messages")
            </button>
        </div>
    }

    @foreach (var msg in Messages)
    {
        <MessageBubble Message="msg"
                       ReplyCount="GetReplyCount(msg.Id)"
                       OnReplyClicked="OnReplyClicked"
                       OnReactionAdded="OnReactionAdded" />
    }

    @if (Messages.Count == 0 && !IsLoadingMore)
    {
        <div class="empty-state">No messages yet. Start the conversation!</div>
    }
</div>

@code {
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnReplyClicked { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReactionAdded { get; set; }

    private ElementReference scrollContainer;

    private int GetReplyCount(int messageId)
    {
        return ThreadReplyCounts.GetValueOrDefault(messageId, 0);
    }
}

